ins.adsbygoogle-noablate[data-anchor-shown="true"]{z-index:990!important}
.content-wrap > .google-auto-placed{display:none!important}
#hidden,.is-empty{display:none}
.CSS_LIGHTBOX{z-index:999999!important}
