.share-a .email{display:none}
.cookie-consent .widget{flex-direction:column}
.consent-button{width:100%}
.share-modal{max-width:calc(100% - 2.75rem)}}
.video-responsive{position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:8px;margin:16px 0;box-shadow:0 4px 16px rgba(0,0,0,.15);margin-bottom:1.3rem!important;}.video-responsive iframe{position:absolute;top:0;left:0;width:100%;height:100%;border:0;}.videoyoutube{margin-bottom:1.5rem;}
.table-responsive-wrapper{display:block;width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch;margin-bottom:1.5em}.table-responsive-wrapper table{width:100%;min-width:600px;border-collapse:collapse}
.table-responsive-wrapper{width:100%;overflow-x:auto}.table-responsive-wrapper .comparison-table{width:100%;border-collapse:collapse;border-spacing:0;font-family:inherit;font-size:16px}.table-responsive-wrapper .comparison-table th,.table-responsive-wrapper .comparison-table td{padding:12px;border:1px solid #01603c;text-align:left;vertical-align:middle}.table-responsive-wrapper .comparison-table th:last-child,.table-responsive-wrapper .comparison-table td:last-child{text-align:center}.table-responsive-wrapper .comparison-table thead tr{background-color:#d0e0d2}.table-responsive-wrapper .comparison-table tbody tr:nth-child(even){background-color:#f9f9f9}.table-responsive-wrapper .comparison-table tbody tr:hover{background-color:#f7f7f7}
@media (max-width: 768px) {
.about-author {flex-direction:column; align-items:center; text-align:center; gap:0.75rem;}
.about-author .author-avatar {width:4.5rem; aspect-ratio:1/1; border-radius:var(--rounded-full); display:block; margin:0 auto; object-fit:cover;}
.about-author .author-title {font-size:1.25rem; margin-top:0.25rem;}
.author-description {width:100%;}
.about-author .author-text {margin-top:0.25rem; line-height:1.6;}
.about-author .social {justify-content:center; gap:0.625rem; margin-top:0.75rem;}
.about-author .social a {width:2.125rem; height:2.125rem;}}
/* ==== CTA UTAMA (.icta) ==== */
.icta {max-width:440px; margin:20px auto; background:#0b7b5a; color:#ffffff; padding:16px 20px; border-radius:16px; text-align:center; border:1px solid rgba(0, 0, 0, 0.18); box-shadow:0 4px 14px rgba(0, 0, 0, 0.2);}
.icta h3 {margin:0 0 12px; font-size:1.05rem; font-weight:700; line-height:1.4;}
.ibtnx {display:inline-block !important; background:#10b981 !important; color:#ffffff !important; padding:8px 16px !important; margin:4px 5px !important; font-size:14px !important; font-weight:600; border-radius:999px !important; border:1px solid #059669 !important; text-decoration:none !important; cursor:pointer; line-height:1.3; white-space:nowrap; box-shadow:0 2px 6px rgba(0,0,0,0.15); transition:transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;}
.ibtnx span {color:inherit !important;}
.ibtnx:hover, .ibtnx:focus-visible {background:#0ea972 !important; box-shadow:0 3px 10px rgba(0,0,0,0.25); transform:translateY(-1px);}
.ismall {margin-top:12px; opacity:0.95; font-size:12px; line-height:1.5;}
.ismall span {color:#fdfdfd;}
.icta-files {margin:10px auto 8px; font-size:0.9rem;}
.icta-files a {display:inline-block; margin:3px 4px; text-decoration:none; color:inherit;}

@media (max-width: 600px) {
.icta {max-width:100%; margin:16px auto; padding:14px 12px; border-radius:14px;}
.icta h3 {font-size:1rem;}
.ibtnx {display:block !important; width:100%; box-sizing:border-box; margin:4px 0 !important; white-space:normal; padding:9px 12px !important; font-size:13px !important;}
.icta-files {font-size:0.85rem;}}

.post-body img:not(.lcp-image) {aspect-ratio:auto; max-width:100%; height:auto; content-visibility:auto;}
.post-body img.lcp-image {aspect-ratio:auto; max-width:100%; height:auto;}
.thumbnail {contain:layout style paint; content-visibility:auto; contain-intrinsic-size:72px 72px;}
/* --- CLS Prevention for Sulvo/Ad units --- */
.demand-supply{display:block;min-height:100px;width:100%}
.rr-container .demand-supply{min-height:280px}
ins.adsbygoogle[data-ad-format="auto"]{display:block;min-height:100px}
ins.adsbygoogle[data-ad-slot]{display:block}
/* --- Reading Time display --- */
.ia-reading-time{display:inline-flex;align-items:center;gap:0.25rem;font-size:0.75rem;color:var(--meta-color)}
.ia-reading-time:before{content:"\f64b";font-family:"bootstrap-icons";font-size:0.8rem}
/* --- Visual Breadcrumb --- */
.ia-breadcrumb{padding:0.75rem 0 0.5rem;font-size:0.8rem}
.ia-breadcrumb__list{display:flex;flex-wrap:wrap;align-items:center;gap:0.25rem 0.375rem;list-style:none;padding:0;margin:0}
.ia-breadcrumb__item{display:flex;align-items:center;gap:0.375rem;color:var(--meta-color)}
.ia-breadcrumb__item:not(:last-child):after{content:"/";opacity:.5}
.ia-breadcrumb__link{color:var(--meta-color)}
.ia-breadcrumb__link:hover{color:var(--accent-color)}
.ia-breadcrumb__item--current{color:var(--title-color);font-weight:500}
/* --- Post Hero Image (LCP element — single post pages) --- */
.post-hero{width:100%;margin-bottom:1.5rem;border-radius:var(--rounded);overflow:hidden;background:var(--border-color)}
.post-hero__img{display:block;width:100%;height:auto;aspect-ratio:1200/630;object-fit:cover;max-height:500px}
/* --- Sidebar Search Form --- */
.sidebar-search-form{display:flex;align-items:center;gap:0.5rem;width:100%;height:2.75rem;background:var(--dynamic-bg,var(--widget-bg));border:1px solid var(--border-color);border-radius:var(--rounded);overflow:hidden;padding:0 0.75rem}
.sidebar-search-input{flex:1;width:100%;height:100%;font-size:0.9375rem;color:var(--title-color);background:transparent;border:none;outline:none}
.sidebar-search-input::placeholder{color:var(--meta-color)}
.sidebar-search-btn{display:flex;align-items:center;justify-content:center;font-size:1rem;color:var(--meta-color);background:transparent;border:none;cursor:pointer;padding:0;flex-shrink:0}
.sidebar-search-btn:hover{color:var(--accent-color)}
/* --- Search popup view-all --- */
.main-search .view-all{padding:0.75rem 1.5rem 1.25rem;border-top:1px solid var(--border-color);font-size:0.8125rem}
.main-search .view-all a{color:var(--meta-color)}
.main-search .view-all a:hover{color:var(--accent-color)}
/* --- Telegram share button --- */
.social .telegram a:before,.social .telegram a{color:#229ED9}
/* --- Sitemap page styles --- */
.ia-sitemap__year{margin-bottom:2rem}
.ia-sitemap__year-title{font-size:1.25rem;font-weight:600;color:var(--title-color);padding-bottom:0.5rem;border-bottom:2px solid var(--accent-color);margin-bottom:1rem}
.ia-sitemap__list{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:0.625rem}
.ia-sitemap__item{display:flex;align-items:baseline;gap:0.75rem;font-size:0.875rem}
.ia-sitemap__date{flex-shrink:0;color:var(--meta-color);font-size:0.75rem;min-width:7rem}
.ia-sitemap__link{color:var(--title-color);line-height:1.4}
.ia-sitemap__link:hover{color:var(--accent-color)}
.ia-sitemap__nav{display:flex;flex-wrap:wrap;gap:0.5rem;margin-top:2rem}
.ia-sitemap__page{display:flex;align-items:center;justify-content:center;min-width:2.25rem;height:2.25rem;background:var(--widget-bg);border:1px solid var(--border-color);border-radius:var(--rounded);font-size:0.875rem;color:var(--title-color);cursor:pointer}
.ia-sitemap__page:hover{background:var(--accent-color);color:#fff;border-color:var(--accent-color)}
.ia-sitemap__page--active{background:var(--accent-color);color:#fff;border-color:var(--accent-color);font-weight:600}

b:if.b:template-skin:
html,body#layout .site-outer,body#layout .row{width:auto;padding:0}
body#layout{position:relative;width:auto;max-width:100%;background-color:#fff;padding:95px 5px 0;margin:0 0 0 1px;border-width:1px 0 0;border-color:#eceff1}
body#layout:before{content:"Spotlight - v1.0.0";position:absolute;top:0;left:5px;right:5px;height:95px;font-family:Roboto,sans-serif;font-size:23px;color:#263238;line-height:95px;text-align:center}
body#layout div.section{display:block;background-color:#eceff1!important;margin:0 5px 10px!important;padding:16px 16px 18px!important;border:0}
body#layout .no-items.section{display:block}
body#layout .section h4,body#layout .content-ads-wrap > h4{display:flex;font-family:Roboto,sans-serif;font-size:14px;color:#263238;text-transform:uppercase;text-align:left;line-height:24px;margin:0}
body#layout .section h4:after,body#layout .content-ads-wrap > h4:after{font-size:12px;text-transform:initial;color:#757575;font-weight:400;margin:0 4px}
body#layout .add_widget a{display:-webkit-box;color:#4385f5!important}
body#layout .widget-wrap3{overflow:hidden}
body#layout .widget-content{width:auto;max-width:none;max-height:none;margin:0;border:1px solid #e7e7e8;border-left:0}
body#layout .locked-widget .widget-content{border-left:1px solid #4385f5}
body#layout .locked-widget .widget-content:hover{border-left-color:#33a453}
body#layout div.layout-title{display:-webkit-box;color:#757575}
body#layout .widget .widget-content a.editlink{border-radius:2px}
body#layout .visibility .editlink{background:#4385f5 url(https://1.bp.blogspot.com/--z1wepFalfQ/YOObl8avCFI/AAAAAAAAAE8/Z-iC0j0LLpo7u2ZpHvW0hGaHhBOvVYYaQCLcBGAsYHQ/s48/edit.png) no-repeat center!important;background-size:20px!important}
body#layout .visibility .editlink:hover{background-color:#33a453!important}
body#layout .draggable-widget .widget-wrap2{background:#4385f5 url(https://1.bp.blogspot.com/-ciJD7MVmo10/YORQlzt9a1I/AAAAAAAAAFk/L4fK5cgelFoWX9rZvGFKZdr1d_RM9kfjACLcBGAsYHQ/s68/drag.png) no-repeat 4px 50%!important;background-size:4px auto!important}
body#layout .draggable-widget .widget-wrap1:hover .widget-wrap2{background-color:#33a453!important}
body#layout .visibility .layout-widget-state.visible{background-image:url(https://1.bp.blogspot.com/-aPoC3YxQo6g/YOOeDVSsJqI/AAAAAAAAAFM/oyvPLSJVIRQpAu-g0gZL89g5Caq4_4DeQCLcBGAsYHQ/s48/visibility_on.png)!important;background-size:24px!important}
body#layout .visibility .layout-widget-state.not-visible{background-image:url(https://1.bp.blogspot.com/-x_kkTMRQfHs/YOOeMUjTE8I/AAAAAAAAAFQ/RRj6YLBNuMEHwTB_81304fCxy8dl7h46gCLcBGAsYHQ/s48/visibility_off.png)!important;background-size:24px!important;opacity:1}
body#layout div.layout-widget-description{display:none;font-size:11px;line-height:1.2em}
body#layout #theme-options,body#layout #main-menu .widget{display:block!important}
body#layout div.pbt-panel{background-color:rgba(67,133,245,.15)!important;overflow:hidden!important}
body#layout .pbt-panel > h4:after{content:"- Default Thumbnail and Advanced Options"}
body#layout .pbt-panel .widget{float:left;width:49.5%}
body#layout .pbt-panel .widget-content{border-color:#d5e3fc!important}
body#layout .pbt-panel .LinkList{margin-left:1%}
body#layout .pbt-panel div.layout-widget-description,body#layout .menu-toggle,body#layout .flex-right,body#layout .main-search{display:none}
body#layout .pbt-panel .layout-title{font-size:0;line-height:1}
body#layout .pbt-panel .layout-title:before{content:"Default Thumbnail";font-size:16px!important;line-height:24px}
body#layout .pbt-panel .LinkList .layout-title:before{content:"Advanced Options"}
body#layout .flex-left{display:flex}
body#layout .main-logo,body#layout .main-menu{width:50%}
body#layout .content-wrap{padding:0;margin:0}
body#layout .content-wrap{display:flex;margin:0}
body#layout .main-wrap{width:67%;padding:0}
body#layout .sidebar-wrap{width:33%;padding:0}
body#layout .content-ads-wrap{background-color:#d4ecdb!important;padding:18px 16px;margin:0 5px 10px}
body#layout .content-ads-wrap .section{background-color:#ffffff!important;border:1px solid #d2e4d5}
body#layout .content-ads{display:flex;margin:8px -5px 0}
body#layout .content-ads .section{width:50%}
body#layout #post-ads-3{margin:0!important}
body#layout .footer-sections{display:flex}
body#layout .footer-info,body#layout .footer-widgets{width:50%}
body#layout .footer-bar .container{display:flex}
body#layout #footer-menu,body#layout #footer-copyright{width:50%}
body#layout #header-ads,body#layout #home-ads,body#layout #post-ads-4,body#layout #footer-ads{background-color:#d4ecdb!important}
body#layout #header-ads .widget-content,body#layout #home-ads .widget-content,body#layout #post-ads-4 .widget-content,body#layout #footer-ads .widget-content{border-color:#d2e4d5}
body#layout #main-logo > h4:after{content:"- Main Logo and Dark Logo"}
body#layout #main-menu > h4:after{content:"- Menu Links, Sub Links and Mega Menu"}
body#layout #header-ads > h4:after{content:"- HTML, AdSense or Image"}
body#layout #featured > h4:after,body#layout #trending > h4:after{content:"- Popular Posts, Recent or Label"}
body#layout #home-ads > h4:after{content:"- HTML, AdSense or Image"}
body#layout #main > h4:after{content:"- Default Blog Posts, AdSense In-Feed ADS, Comments and More"}
body#layout .content-ads-wrap > h4:before{content:attr(title)}
body#layout .content-ads-wrap > h4:after{content:"- HTML, AdSense or Image"}
body#layout #post-ads-1 > h4:after,body#layout #post-ads-2 > h4:after{content:"- Posts and Pages"}
body#layout #post-ads-3 > h4:after{content:"- Between Paragraphs via Shortcode (Posts and Pages)"}
body#layout #related-posts > h4:after{content:"- Related, Recent or Label"}
body#layout #post-ads-4 > h4:after{content:"- HTML, AdSense or Image"}
body#layout .sidebar > h4:after{content:"- Default Gadgets"}
body#layout #footer-ads > h4:after{content:"- HTML, AdSense or Image"}
body#layout .footer-info > h4:after{content:"- Site Logo, Description and Social Icons"}
body#layout .footer-widgets > h4:after{content:"- Default Gadgets"}
body#layout #footer-copyright > h4:after{content:"- Custom Credits"}
body#layout #footer-menu > h4:after{content:"- Custom Links"}
body#layout #cookie > h4:after{content:"- Custom Cookie Consent Message"}
body#layout:after{content:"\0000a9\0000a0\Pro Blogger Templates - Core Version (2.2.0)";display:block;font-family:Roboto,sans-serif;font-size:14px;color:rgba(0,0,0,.54);line-height:1;text-align:center;visibility:visible;padding:20px 0 30px}
body#layout #hidden{display:none!important}

