body.script:
//
(function(){
  "use strict";
  const QuranAPI = "https://api.alquran.cloud/v1";
  const QuranCacheTTL = 24*60*60*1000; // 1 day
  const QuranReciters = {
    alafasy: "ar.alafasy",
    maher: "ar.maher",
    mishary: "ar.mishary",
    minshawi: "ar.minshawi",
    ayyub: "ar.ayyub"
  };
  function cacheKey(key){return `quran_${key}`;}
  function getCache(key){try{const v=localStorage.getItem(cacheKey(key));if(!v) return null;const d=JSON.parse(v);if(Date.now()-d.ts>QuranCacheTTL) return null;return d.v;}catch(e){return null;}}
  function setCache(key,val){try{localStorage.setItem(cacheKey(key),JSON.stringify({ts:Date.now(),v:val}));}catch(e){}}
  async function fetchJson(url){const res=await fetch(url);if(!res.ok) throw new Error(res.statusText);return res.json();}
  async function getSurah(number,reciter){const edition=QuranReciters[reciter]||QuranReciters.alafasy;const key=`surah_${number}_${edition}`;const cached=getCache(key);if(cached) return cached;try{const data=await fetchJson(`${QuranAPI}/surah/${number}/${edition}`);setCache(key,data);return data;}catch(e){console.warn("Al Quran Cloud failed, trying Tanzil fallback:",e);const fallbackUrl=`https://cdn.jsdelivr.net/npm/tanzil@latest/quran/uthmani/${number}.json`;const fallbackData=await fetchJson(fallbackUrl);const data={data:{ayahs:fallbackData.ayahs.map((a,i)=>({numberInSurah:i+1,text:a}))}};setCache(key,data);return data;}}
  async function getAyah(number,ayah,reciter){const data=await getSurah(number,reciter);return data.data.ayahs.find(a=>a.numberInSurah==ayah);}
  async function playAyah(number,ayah,reciter){try{const ayahData=await getAyah(number,ayah,reciter);if(!ayahData||!ayahData.audio) throw new Error("Audio not found");let audio=document.getElementById("quran-audio-player");if(!audio){audio=document.createElement("audio");audio.id="quran-audio-player";audio.controls=true;audio.style.display="none";document.body.appendChild(audio);}audio.src=ayahData.audio;await audio.play();return audio;}catch(e){console.warn("Quran audio error:",e);throw e;}}
  function renderSurah(number,container,reciter){const el=typeof container==="string"?document.querySelector(container):container;if(!el) return;getSurah(number,reciter).then(data=>{const html=data.data.ayahs.map(a=>`<div class="quran-ayah" data-surah="${number}" data-ayah="${a.numberInSurah}"><div class="quran-ayah-number">${a.numberInSurah}</div><div class="quran-ayah-text">${a.text}</div></div>`).join("");el.innerHTML=html;}).catch(()=>{if(el) el.innerHTML='<div class="quran-error">Tidak dapat memuat Al-Quran. Sila cuba lagi.</div>';});}
  function createPlayer(container,surah,ayah){const el=typeof container==="string"?document.querySelector(container):container;if(!el) return;const html=`<div class="quran-player"><select class="quran-reciter"><option value="alafasy">Mishary Rashid Alafasy</option><option value="maher">Maher Al Mueaqly</option><option value="mishary">Mishary Rashid (Alt)</option><option value="minshawi">Minshawi</option><option value="ayyub">Ayyub</option></select><button class="quran-play-btn btn">Play Ayah ${ayah}</button></div>`;el.innerHTML=html;const select=el.querySelector('.quran-reciter'),btn=el.querySelector('.quran-play-btn');btn.onclick=()=>playAyah(surah,ayah,select.value).catch(e=>alert('Audio error: '+e.message));}
  window.Quran={reciters:QuranReciters,getSurah,getAyah,playAyah,renderSurah,createPlayer};
  window.getAyah=async function(number,ayah,reciter){return window.Quran.getAyah(number,ayah,reciter);};
  window.playAyah=async function(number,ayah,reciter){return window.Quran.playAyah(number,ayah,reciter);};
  window.renderSurah=window.Quran.renderSurah;
  window.createQuranPlayer=window.Quran.createPlayer;
})();
//

//
(function(){
  "use strict";
  function injectReadingTime(){
    var body=document.querySelector(".post-body");
    var el=document.querySelector(".ia-reading-time");
    if(!body||!el) return;
    var words=(body.innerText||body.textContent||"").trim().split(/\s+/).filter(function(w){return w.length>0;}).length;
    var mins=Math.max(1,Math.ceil(words/200));
    el.textContent=mins+(mins===1?" minit bacaan":" minit bacaan");
  }
  if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",injectReadingTime,{once:true,passive:true});}
  else{injectReadingTime();}
})();
//

//
(function($){
  "use strict";
  $(function(){
    var $modal=$(".main-search");
    if(!$modal.length) return;
    var $input=$modal.find("input[name='q'],input.input");
    var $results=$modal.find(".search-results");
    var $sc=$results.parent();
    var $va=$("#search-view-all");
    var timer,lastQ,cbCount=0;

    // Replace input handler set by main script
    $input.off("input").on("input",function(){
      clearTimeout(timer);
      var q=$input.val().trim();
      if(!q){
        lastQ="";
        $results.html("").removeClass("scroll");
        $sc.removeClass("visible");
        $modal.removeClass("loading");
        $va.attr("href","/search").text("Lihat semua hasil");
        return;
      }
      $va.attr("href","/search?q="+encodeURIComponent(q))
         .text("Lihat semua hasil untuk “"+q+"”");
      timer=setTimeout(function(){iaSearch(q);},500);
    });

    function iaSearch(q){
      if(q===lastQ) return;
      lastQ=q;
      $results.removeClass("scroll");
      $modal.addClass("loading");
      $sc.addClass("visible");

      var cbName="ia_srch_"+Date.now()+(++cbCount);
      var s=document.createElement("script");
      var done=false;

      function cleanup(){
        if(s.parentNode) s.parentNode.removeChild(s);
        delete window[cbName];
      }

      window[cbName]=function(data){
        done=true;
        cleanup();
        $modal.removeClass("loading");
        var entries=(data.feed&&data.feed.entry)||[];
        if(!entries.length){
          $results.html("<span class='error-msg'>"+(typeof pbt!=="undefined"?pbt.noResults:"Tiada hasil ditemui")+"</span>").addClass("scroll");
          return;
        }
        var html="<div class='search-items'>";
        entries.slice(0,12).forEach(function(en){
          var title=en.title.$t;
          var url="";
          (en.link||[]).forEach(function(l){if(l.rel==="alternate") url=l.href;});
          var thumb="";
          if(en.media$thumbnail) thumb=en.media$thumbnail.url.replace(/\/s[0-9]+-c/,"/s160-c");
          var date="";
          if(en.published) date=en.published.$t.slice(0,10);
          html+="<div class='post flex-sb'>";
          if(thumb) html+="<a class='thumbnail sm' href='"+url+"'><img class='lazy' data-src='"+thumb+"' alt='' height='80' loading='lazy' width='80'/></a>";
          html+="<div class='post-info flex-col'><a class='entry-title' href='"+url+"'>"+title+"</a>";
          if(date) html+="<time class='entry-date'>"+date+"</time>";
          html+="</div></div>";
        });
        html+="</div>";
        $results.html(html).addClass("scroll");
        if(typeof $.fn.pbtLazy==="function") $results.find(".lazy").pbtLazy({onScroll:false});
      };

      s.onerror=function(){
        if(done) return;
        cleanup();
        $modal.removeClass("loading");
        $results.html("<span class='error-msg'>"+(typeof pbt!=="undefined"?pbt.noResults:"Tiada hasil ditemui")+"</span>").addClass("scroll");
      };

      s.src="/feeds/posts/summary?q="+encodeURIComponent(q)+"&max-results=12&alt=json-in-script&callback="+cbName;
      document.head.appendChild(s);
    }
  });
})(jQuery);
//

//
(function(){
  "use strict";
  var container=document.getElementById("ia-sitemap-posts");
  var nav=document.getElementById("ia-sitemap-nav");
  if(!container) return;
  var BLOG="https://www.ilmualam.com";
  var FEED_BATCH=150;
  var PAGE_SIZE=100;
  var months=["Jan","Feb","Mac","Apr","Mei","Jun","Jul","Ogos","Sep","Okt","Nov","Dis"];
  var allPosts=[];
  var total=0;
  var current=1;
  function escapeHtml(str){return String(str||"").replace(/[&<>\"']/g,function(ch){return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[ch];});}
  function loadJsonp(url,callbackName,done){var s=document.createElement("script");window[callbackName]=function(data){cleanup();done(null,data);};s.onerror=function(){cleanup();done(new Error("jsonp_failed"));};function cleanup(){try{delete window[callbackName];}catch(e){window[callbackName]=void 0;}if(s.parentNode) s.parentNode.removeChild(s);}s.async=true;s.src=url+(url.indexOf("?")>-1?"&":"?")+"alt=json-in-script&callback="+callbackName;document.head.appendChild(s);}
  function getPostUrl(entry){var links=entry.link||[];for(var i=0;i<links.length;i++){if(links[i].rel==="alternate") return links[i].href;}return "#";}
  function normalizeEntry(entry){var dateStr=((entry.published&&entry.published.$t)||"").substring(0,10);var parts=dateStr?dateStr.split("-"):["","",""];var year=parts[0]||"";var month=Math.max(0,(parseInt(parts[1],10)||1)-1);var day=parts[2]||"";return {url:getPostUrl(entry),title:(entry.title&&entry.title.$t)||"",date:(year?months[month]+" "+day+", "+year:""),year:year,published:(entry.published&&entry.published.$t)||""};}
  function renderPage(page){current=page;var start=(page-1)*PAGE_SIZE;var slice=allPosts.slice(start,start+PAGE_SIZE);if(!slice.length){container.innerHTML="<p style='padding:2rem;text-align:center'>Tiada artikel dijumpai.</p>";if(nav) nav.innerHTML="";return;}var byYear={};slice.forEach(function(post){if(!byYear[post.year]) byYear[post.year]=[];byYear[post.year].push(post);});var years=Object.keys(byYear).sort(function(a,b){return Number(b)-Number(a);});var html="";years.forEach(function(year){html+="<div class='ia-sitemap__year'><h3 class='ia-sitemap__year-title'>"+escapeHtml(year)+"</h3><ul class='ia-sitemap__list'>";byYear[year].forEach(function(post){html+="<li class='ia-sitemap__item'><span class='ia-sitemap__date'>"+escapeHtml(post.date)+"</span><a class='ia-sitemap__link' href='"+post.url+"'>"+escapeHtml(post.title)+"</a></li>";});html+="</ul></div>";});container.innerHTML=html;if(nav){var totalPages=Math.ceil(allPosts.length/PAGE_SIZE);if(totalPages>1){var navHtml="<nav class='ia-sitemap__nav' aria-label='Navigasi Sitemap'>";for(var i=1;i<=totalPages;i++){var active=i===current?" ia-sitemap__page--active":"";navHtml+="<button class='ia-sitemap__page"+active+"' data-page='"+i+"' type='button'>"+i+"</button>";}navHtml+="</nav>";nav.innerHTML=navHtml;}else{nav.innerHTML="";}}}
  function fetchBatch(start){var callbackName="ia_sm_batch_"+start;loadJsonp(BLOG+"/feeds/posts/summary?start-index="+start+"&max-results="+FEED_BATCH,callbackName,function(err,data){if(err){container.innerHTML="<p style='padding:2rem;text-align:center'>Sitemap gagal dimuatkan. Sila cuba lagi.</p>";if(nav) nav.innerHTML="";return;}var entries=(data.feed&&data.feed.entry)||[];var fetchedTotal=0;try{fetchedTotal=parseInt(data.feed.openSearch$totalResults.$t,10)||0;}catch(e){fetchedTotal=0;}if(!total) total=fetchedTotal;allPosts=allPosts.concat(entries.map(normalizeEntry));if(entries.length===FEED_BATCH && allPosts.length<total){fetchBatch(start+FEED_BATCH);return;}allPosts.sort(function(a,b){return new Date(b.published).getTime()-new Date(a.published).getTime();});renderPage(1);});}
  if(nav){nav.addEventListener("click",function(event){var btn=event.target.closest("[data-page]");if(!btn) return;var page=parseInt(btn.getAttribute("data-page"),10);if(!page || page===current) return;window.scrollTo({top:0,behavior:"smooth"});renderPage(page);});}
  function init(){container.innerHTML="<p style='text-align:center;padding:2rem;color:var(--meta-color)'>Memuatkan sitemap...</p>";fetchBatch(1);}
  if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init,{once:true,passive:true});}else{init();}
})();
//
